def transform(grid):
    h, w = len(grid), len(grid[0])

    # The rare nonzero color is the stamp.
    counts = {}
    for row in grid:
        for value in row:
            if value != 0:
                counts[value] = counts.get(value, 0) + 1
    stamp_color = min(counts, key=counts.get)

    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] == stamp_color]
    min_r = min(r for r, c in cells)
    max_r = max(r for r, c in cells)
    min_c = min(c for r, c in cells)
    max_c = max(c for r, c in cells)
    shape = [(r - min_r, c - min_c) for r, c in cells]
    sh, sw = max_r - min_r + 1, max_c - min_c + 1

    original = [row[:] for row in grid]
    out = [row[:] for row in grid]
    for r in range(h - sh + 1):
        for c in range(w - sw + 1):
            if all(original[r + dr][c + dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[r + dr][c + dc] = stamp_color
    return out
